<?php
namespace App\Http\Controllers; use App\Models\User; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
final class AuthController extends Controller { public function login(Request $r):JsonResponse{$d=$r->validate(['email'=>['required','email'],'password'=>['required','string']]);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password))return response()->json(['error'=>['type'=>'unauthenticated','message'=>'The credentials were not accepted.'],'request_id'=>$r->attributes->get('request_id')],401);Auth::login($u);$r->session()->regenerate();return $this->me($r);} public function logout(Request $r):JsonResponse{Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->json([],204);} public function me(Request $r):JsonResponse{$u=$r->user();return response()->json(['user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'memberships'=>$u->memberships()->where('status','active')->get(['organization_id','role'])]]);} }
